E = lambda x: html.escape(str(x), quote=True)

def t(zh, en, tag='span', attrs=''):
    return f'<{tag} data-zh="{E(zh)}" data-en="{E(en)}" {attrs}>{E(zh)}</{tag}>'

def p(zh, en, cls=''):
    return t(zh, en, 'p', f'class="{cls}"' if cls else '')

def link(url, zh, en, cls=''):
    external = ' target="_blank" rel="noopener noreferrer"' if url.startswith('https://') else ''
    return t(zh, en, 'a', f'href="{E(url)}" class="{cls}"{external}')

def source(url, zh, en):
    return '<p class="source">' + link(url, zh, en) + '</p>'

def section(id, num, zh, en, desc=None):
    s = f'<section class="guide-section" id="{id}"><div class="section-heading"><span class="section-number">{num}</span>' + t(zh,en,'h2') + '</div>'
    return s + (p(*desc, cls='section-intro') if desc else '')

def list_items(items, ordered=False):
    tag='ol' if ordered else 'ul'
    return f'<{tag}>' + ''.join(t(*x,'li') for x in items) + f'</{tag}>'

def details(zh,en,body,opened=False):
    return '<details class="note-details"'+(' open' if opened else '')+'><summary>'+t(zh,en)+'</summary><div class="details-inner">'+body+'</div></details>'

def table(headers, rows, caption):
    return '<div class="table-scroll" tabindex="0" role="region" aria-label="Course comparison / 课程比较"><table><caption>'+t(*caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+t(*h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<'+('th scope="row"' if j==0 else 'td')+'>'+cell+'</'+('th' if j==0 else 'td')+'>' for j,cell in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'

